1	"use client";
2	
3	/**
4	 * GameHero — an animated, per-game-themed hero for the game-server SEO landing
5	 * pages. It renders the SAME content structure as <PageHero> (logo → eyebrow →
6	 * title+highlight → sub → CTAs) so copy and layout stay identical across pages,
7	 * but sits it on a live themed particle field coloured by the game's own brand
8	 * gradient (GAME_VISUAL in GameLogo.tsx).
9	 *
10	 * The motion is per-game: Minecraft/Bedrock drift like voxels, Valheim/Enshrouded
11	 * and Project Zomboid fall like snow/ash, Rust/7DTD/Factorio rise like embers.
12	 * Everything is coloured from the family's from/to stops, so a new game "just
13	 * works" the moment it has a GAME_VISUAL entry — no per-page art.
14	 *
15	 * Performance + a11y: one capped requestAnimationFrame loop on a DPR-scaled
16	 * canvas, paused when the hero scrolls out of view; under prefers-reduced-motion
17	 * (or with no canvas support) it renders a static themed aura and never animates.
18	 */
19	
20	import Link from "next/link";
21	import { useEffect, useRef, useState } from "react";
22	import { Eyebrow } from "@/components/marketing/primitives";
23	import { GameLogo, GAME_VISUAL } from "@/components/marketing/GameLogo";
24	import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";
25	
26	type Cta = { label: string; href: string };
27	
28	type Motif = "rise" | "fall" | "drift";
29	
30	/** How each family's particles move. Falls back to "drift". */
31	const MOTIF: Record<string, Motif> = {
32	  minecraft: "drift",
33	  bedrock: "drift",
34	  valheim: "fall",
35	  enshrouded: "fall",
36	  theforest: "fall",
37	  sonsoftheforest: "fall",
38	  projectzomboid: "fall",
39	  vrising: "fall",
40	  rust: "rise",
41	  sdtd: "rise",
42	  conan: "rise",
43	  cs2: "rise",
44	  factorio: "rise",
45	  palworld: "drift",
46	  terraria: "drift",
47	  ark: "drift",
48	  satisfactory: "drift",
49	  gmod: "drift",
50	  unturned: "drift",
51	};
52	
53	/** Families whose particles read better as little squares (voxel / pixel / industrial). */
54	const SQUARE = new Set(["minecraft", "bedrock", "factorio", "terraria", "satisfactory"]);
55	
56	type P = { x: number; y: number; r: number; vx: number; vy: number; a: number; rot: number; vr: number };
57	
58	export function GameHero({
59	  family,
60	  eyebrow = "Game servers",
61	  title,
62	  highlight,
63	  sub,
64	  primary,
65	  secondary,
66	}: {
67	  family: string;
68	  eyebrow?: string;
69	  title: React.ReactNode;
70	  highlight?: string;
71	  sub?: React.ReactNode;
72	  primary?: Cta;
73	  secondary?: Cta;
74	}) {
75	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
76	  const visual = GAME_VISUAL[family] ?? { from: "#334155", to: "#64748b" };
77	  const motif = MOTIF[family] ?? "drift";
78	  const square = SQUARE.has(family);
79	  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;
80	  const [heroFailed, setHeroFailed] = useState(false);
81	
82	  useEffect(() => {
83	    const canvas = canvasRef.current;
84	    if (!canvas) return;
85	    const reduce =
86	      typeof window !== "undefined" &&
87	      window.matchMedia &&
88	      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
89	    if (reduce) return; // static aura only
90	
91	    const ctx = canvas.getContext("2d");
92	    if (!ctx) return;
93	
94	    const hexToRgb = (hex: string) => {
95	      const h = hex.replace("#", "");
96	      const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
97	      return [(n >> 16) & 255, (n >> 8) & 255, n & 255] as const;
98	    };
99	    const [fr, fg, fb] = hexToRgb(visual.from);
100	    const [tr, tg, tb] = hexToRgb(visual.to);
101	
102	    let w = 0;
103	    let h = 0;
104	    let dpr = 1;
105	    let particles: P[] = [];
106	    let raf = 0;
107	    let running = true;
108	
109	    const seed = (p: P, initial: boolean) => {
110	      p.r = 1 + Math.random() * (square ? 4 : 3);
111	      p.a = 0.15 + Math.random() * 0.45;
112	      p.rot = Math.random() * Math.PI;
113	      p.vr = (Math.random() - 0.5) * 0.02;
114	      const speed = 0.15 + Math.random() * 0.5;
115	      if (motif === "rise") {
116	        p.x = Math.random() * w;
117	        p.y = initial ? Math.random() * h : h + 10;
118	        p.vx = (Math.random() - 0.5) * 0.25;
119	        p.vy = -speed;
120	      } else if (motif === "fall") {
121	        p.x = Math.random() * w;
122	        p.y = initial ? Math.random() * h : -10;
123	        p.vx = (Math.random() - 0.5) * 0.35;
124	        p.vy = speed;
125	      } else {
126	        p.x = Math.random() * w;
127	        p.y = Math.random() * h;
128	        const ang = Math.random() * Math.PI * 2;
129	        p.vx = Math.cos(ang) * speed * 0.5;
130	        p.vy = Math.sin(ang) * speed * 0.5;
131	      }
132	    };
133	
134	    const resize = () => {
135	      const rect = canvas.getBoundingClientRect();
136	      dpr = Math.min(window.devicePixelRatio || 1, 2);
137	      w = rect.width;
138	      h = rect.height;
139	      canvas.width = Math.round(w * dpr);
140	      canvas.height = Math.round(h * dpr);
141	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
142	      // Density scales with area but is capped so big screens stay cheap.
143	      const count = Math.min(90, Math.round((w * h) / 14000));
144	      particles = Array.from({ length: count }, () => {
145	        const p: P = { x: 0, y: 0, r: 0, vx: 0, vy: 0, a: 0, rot: 0, vr: 0 };
146	        seed(p, true);
147	        return p;
148	      });
149	    };
150	
151	    const draw = () => {
152	      ctx.clearRect(0, 0, w, h);
153	      for (const p of particles) {
154	        p.x += p.vx;
155	        p.y += p.vy;
156	        p.rot += p.vr;
157	        // recycle when off-canvas
158	        if (p.y < -12 || p.y > h + 12 || p.x < -12 || p.x > w + 12) seed(p, false);
159	        // colour: lerp between the two brand stops by vertical position
160	        const t = Math.max(0, Math.min(1, p.y / h));
161	        const r = Math.round(fr + (tr - fr) * t);
162	        const g = Math.round(fg + (tg - fg) * t);
163	        const b = Math.round(fb + (tb - fb) * t);
164	        ctx.globalAlpha = p.a;
165	        ctx.fillStyle = `rgb(${r},${g},${b})`;
166	        if (square) {
167	          ctx.save();
168	          ctx.translate(p.x, p.y);
169	          ctx.rotate(p.rot);
170	          ctx.fillRect(-p.r, -p.r, p.r * 2, p.r * 2);
171	          ctx.restore();
172	        } else {
173	          ctx.beginPath();
174	          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
175	          ctx.fill();
176	        }
177	      }
178	      ctx.globalAlpha = 1;
179	      if (running) raf = requestAnimationFrame(draw);
180	    };
181	
182	    resize();
183	    running = true;
184	    raf = requestAnimationFrame(draw);
185	
186	    const onResize = () => resize();
187	    window.addEventListener("resize", onResize);
188	
189	    // Pause the loop when the hero is scrolled away (saves battery/CPU).
190	    const io =
191	      typeof IntersectionObserver !== "undefined"
192	        ? new IntersectionObserver(
193	            ([e]) => {
194	              if (e.isIntersecting && !running) {
195	                running = true;
196	                raf = requestAnimationFrame(draw);
197	              } else if (!e.isIntersecting && running) {
198	                running = false;
199	                cancelAnimationFrame(raf);
200	              }
201	            },
202	            { threshold: 0 },
203	          )
204	        : null;
205	    io?.observe(canvas);
206	
207	    return () => {
208	      running = false;
209	      cancelAnimationFrame(raf);
210	      window.removeEventListener("resize", onResize);
211	      io?.disconnect();
212	    };
213	  }, [family, motif, square, visual.from, visual.to]);
214	
215	  return (
216	    <section className="relative overflow-hidden">
217	      {/* Real per-game hero photo, dimmed + blurred so the title/CTAs stay the
218	          focal point — the same treatment as the /game-servers carousel's
219	          backdrop. Sits BEHIND the themed aura/particles (DOM order), and
220	          onError just removes it (never a broken image; the aura+particles
221	          alone are still a complete hero). */}
222	      {heroSlug && !heroFailed && (
223	        // eslint-disable-next-line @next/next/no-img-element
224	        <img
225	          src={`/games/art/${heroSlug}_hero.jpg`}
226	          alt=""
227	          aria-hidden
228	          onError={() => setHeroFailed(true)}
229	          className="pointer-events-none absolute inset-0 -z-20 h-full w-full scale-110 object-cover object-center opacity-45 blur-md"
230	        />
231	      )}
232	      {/* Static themed aura — always present, and the ONLY visual under reduced-motion. */}
233	      <div
234	        className="pointer-events-none absolute inset-0 -z-10"
235	        aria-hidden
236	        style={{
237	          background: `radial-gradient(60% 60% at 20% 0%, ${visual.from}22, transparent 70%), radial-gradient(55% 55% at 90% 20%, ${visual.to}22, transparent 70%)`,
238	        }}
239	      />
240	      {/* Animated particle field (no-op under reduced-motion). */}
241	      <canvas ref={canvasRef} className="pointer-events-none absolute inset-0 -z-10 h-full w-full" aria-hidden />
242	      {/* Fade the field into the page so particles never hit the hard section edge. */}
243	      <div
244	        className="pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-32 bg-gradient-to-b from-transparent to-navy-950"
245	        aria-hidden
246	      />
247	
248	      <div className="rail py-20 sm:py-28">
249	        <div className="mx-auto max-w-3xl text-center">
250	          <div className="mb-5 flex justify-center">
251	            <span className="inline-flex motion-safe:animate-gh-pop">
252	              <GameLogo family={family} size={72} />
253	            </span>
254	          </div>
255	          <Eyebrow pill>{eyebrow}</Eyebrow>
256	          <h1 className="mt-5 text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
257	            {title}
258	            {highlight && (
259	              <>
260	                {" "}
261	                <span className="grad-text">{highlight}</span>
262	              </>
263	            )}
264	          </h1>
265	          {sub && (
266	            <p className="mx-auto mt-6 max-w-2xl text-lg leading-relaxed text-slate-400 sm:text-xl">{sub}</p>
267	          )}
268	          {(primary || secondary) && (
269	            <div className="mt-9 flex flex-wrap justify-center gap-3">
270	              {primary && (
271	                <Link href={primary.href} className="btn-deploy px-5 py-3 text-base">
272	                  {primary.label}
273	                  <span className="dep-arrow" aria-hidden>→</span>
274	                </Link>
275	              )}
276	              {secondary && (
277	                <Link href={secondary.href} className="btn-secondary px-5 py-3 text-base">
278	                  {secondary.label}
279	                </Link>
280	              )}
281	            </div>
282	          )}
283	        </div>
284	      </div>
285	    </section>
286	  );
287	}
