4	
5	/**
6	 * ReviewCarousel — a compact, auto-sliding single-card carousel for the
7	 * homepage's social-proof section. Both review sources (real, approved
8	 * <CustomerReviews/> and the illustrative <Testimonials/> fallback) used to
9	 * render as a full grid of up to 6 cards each — with both sources live at
10	 * once that's up to 12 stacked cards, a major contributor to homepage length.
11	 * This condenses either source down to one card's worth of vertical space,
12	 * auto-advancing through the rest.
13	 *
14	 * Deliberately simple compared to the game-cover coverflow carousel — no
15	 * drag/momentum, just a timed crossfade + slide, dot indicators, and the same
16	 * autoplay-pause rules used elsewhere on the site (hover, focus, tab-hidden,
17	 * prefers-reduced-motion).
18	 */
19	
20	export type ReviewCarouselItem = {
21	  id: string;
22	  quote: string;
23	  name: string;
24	  meta: string;
25	  avatar: string; // initial letter or emoji
26	  rating?: number; // 1-5; omitted → no star row (illustrative use-cases)
27	};
28	
29	function Stars({ rating }: { rating: number }) {
30	  const filled = Math.max(0, Math.min(5, rating));
31	  return (
32	    <span className="text-sm tracking-wide" aria-hidden>
33	      <span className="text-amber-400">{"★".repeat(filled)}</span>
34	      <span className="text-slate-700">{"★".repeat(5 - filled)}</span>
35	    </span>
36	  );
37	}
38	
39	export function ReviewCarousel({ items, intervalMs = 5200 }: { items: ReviewCarouselItem[]; intervalMs?: number }) {
40	  const n = items.length;
41	  const [active, setActive] = useState(0);
42	  const [paused, setPaused] = useState(false);
43	  const reducedRef = useRef(false);
44	  const activeRef = useRef(0);
45	
46	  useEffect(() => {
47	    reducedRef.current = typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
48	  }, []);
49	
50	  useEffect(() => {
51	    if (paused || reducedRef.current || n <= 1) return;
52	    const id = window.setInterval(() => {
53	      if (document.hidden) return;
54	      const next = activeRef.current + 1 >= n ? 0 : activeRef.current + 1;
55	      activeRef.current = next;
56	      setActive(next);
57	    }, intervalMs);
58	    return () => window.clearInterval(id);
59	  }, [paused, n, intervalMs]);
60	
61	  if (n === 0) return null;
62	
63	  const go = (i: number) => {
64	    const idx = ((i % n) + n) % n;
65	    activeRef.current = idx;
66	    setActive(idx);
67	  };
68	
69	  const t = items[active];
70	
71	  return (
72	    <div
73	      className="mx-auto max-w-2xl"
74	      onMouseEnter={() => setPaused(true)}
75	      onMouseLeave={() => setPaused(false)}
76	      onFocusCapture={() => setPaused(true)}
77	      onBlurCapture={() => setPaused(false)}
78	    >
79	      <div
80	        role="group"
81	        aria-roledescription="carousel"
82	        aria-label="Customer reviews"
83	        tabIndex={0}
84	        onKeyDown={(e) => {
85	          if (e.key === "ArrowLeft") go(active - 1);
86	          else if (e.key === "ArrowRight") go(active + 1);
87	        }}
88	        className="card relative min-h-[13rem] overflow-hidden outline-none focus-visible:ring-2 focus-visible:ring-brand-500/40"
89	      >
90	        <div key={t.id} className="flex h-full flex-col items-center text-center motion-safe:animate-[var(--animate-price-pop)]">
91	          {t.rating != null && <Stars rating={t.rating} />}
92	          <p className="mt-4 flex-1 text-sm leading-relaxed text-slate-300">&ldquo;{t.quote}&rdquo;</p>
93	          <div className="mt-5 flex flex-col items-center gap-2 border-t border-white/[0.06] pt-4">
94	            <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-base font-semibold text-brand-200">
95	              {t.avatar}
96	            </span>
97	            <span className="min-w-0">
98	              <span className="block text-sm font-semibold text-white">{t.name}</span>
99	              <span className="block text-xs text-slate-500">{t.meta}</span>
100	            </span>
101	          </div>
102	        </div>
103	      </div>
104	
105	      {/* Live region so screen readers hear the review change without re-announcing the whole card. */}
106	      <p className="sr-only" aria-live="polite">
107	        Review {active + 1} of {n}: {t.name}
108	      </p>
109	
110	      {n > 1 && (
111	        <div className="mt-4 flex items-center justify-center gap-2">
112	          {items.map((it, i) => (
113	            <button
114	              key={it.id}
115	              type="button"
116	              aria-label={`Show review ${i + 1} of ${n}`}
117	              aria-current={i === active}
118	              onClick={() => go(i)}
119	              className={`h-1.5 rounded-full transition-all ${i === active ? "w-6 bg-brand-400" : "w-1.5 bg-white/25 hover:bg-white/45"}`}
120	            />
121	          ))}
122	        </div>
123	      )}
124	    </div>
125	  );
126	}
