import type { GameFamily } from "@/lib/games";

/**
 * PREVIEW-ONLY sample data for the three new game-landing DIRECTIONS
 * (components/marketing/gamelanding/*). Nothing here touches the live
 * GameLandingPage or any *-server-hosting route — it exists purely so the
 * preview routes render with realistic, game-specific content.
 *
 * Plans/prices are pulled from the real live pages (rust-server-hosting,
 * satisfactory-server-hosting, palworld) so the mock reads true. Reviews are
 * ILLUSTRATIVE sample content (same status as the existing <Testimonials/>),
 * kept modest and honest — no fabricated server counts.
 */

export type PreviewPlan = {
  id: string;
  /** Short tier label, e.g. "Wipe" / "Community". */
  tier: string;
  /** RAM headline, e.g. "6 GB". */
  ram: string;
  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
  price: string;
  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
  meta: string;
  blurb: string;
  popular?: boolean;
  features: string[];
};

/** Icon keys resolved to real <Icon*> components inside the client kit. */
export type IconKey =
  | "bolt"
  | "apps"
  | "terminal"
  | "shield"
  | "gauge"
  | "users"
  | "backup"
  | "globe"
  | "scale";

export type PreviewReason = {
  n: string;
  title: string;
  body: string;
  icon: IconKey;
};

export type PreviewReview = {
  id: string;
  quote: string;
  name: string;
  meta: string;
  rating: number;
};

export type PreviewGame = {
  family: GameFamily;
  /** public/games/art/<artSlug>_hero.jpg + _poster.jpg */
  artSlug: string;
  name: string;
  /** Small uppercase category line. */
  kicker: string;
  /** Hero headline (plain) + gradient highlight fragment. */
  headline: string;
  highlight: string;
  /** One-line deck under the headline. */
  deck: string;
  fromPrice: string;
  /** Art-derived, on-brand accent (violet / cyan family). */
  accent: string;
  /** Second art-derived hue, ambient glows only. */
  glow: string;
  /** Live-panel identity. */
  worldName: string;
  region: string;
  /** Terminal boot lines for the console direction. */
  boot: string[];
  plans: PreviewPlan[];
  reasons: PreviewReason[];
  reviews: PreviewReview[];
  /** Aggregate social proof (soft, honest). */
  ratingAvg: string;
  ratingLabel: string;
};

const RUST: PreviewGame = {
