      blurb: "A vanilla or lightly-modded wipe for a small crew starting out.",
      features: ["40 player slots", "One-click Oxide/uMod", "Full FTP access", "Instant setup"],
    },
    {
      id: "rust-6",
      tier: "Community",
      ram: "6 GB",
      price: "$17.99",
      meta: "60 slots",
      blurb: "The popular pick for an active modded server with Oxide plugins.",
      popular: true,
      features: ["60 player slots", "One-click Oxide/uMod", "Custom maps + full FTP", "DDoS protected", "Scheduled wipes"],
