"use client";

/**
 * Shared client-side kit for the three preview game-landing directions.
 * Small, dependency-free hooks + presentational atoms so each direction stays
 * focused on its own layout/motion identity. Everything here respects
 * prefers-reduced-motion: motion hooks resolve to their final resting value.
 */

import { useEffect, useRef, useState } from "react";
import type { IconKey } from "./data";
import {
  IconBolt,
  IconApps,
  IconTerminal,
  IconShield,
  IconGauge,
  IconUsers,
  IconBackup,
  IconGlobe,
  IconScale,
} from "@/components/marketing/icons";

/* ── hooks ─────────────────────────────────────────────────────────────── */

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!mq) return;
    setReduced(mq.matches);
    const on = () => setReduced(mq.matches);
    mq.addEventListener?.("change", on);
    return () => mq.removeEventListener?.("change", on);
  }, []);
  return reduced;
}

/** Fires once when the element first scrolls into view. */
export function useInViewOnce<T extends HTMLElement = HTMLDivElement>(margin = "0px 0px -12% 0px") {
  const ref = useRef<T | null>(null);
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") {
      setSeen(true);
      return;
    }
    const io = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setSeen(true);
          io.disconnect();
        }
      },
      { threshold: 0.15, rootMargin: margin },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [margin]);
  return { ref, seen };
}

/**
 * Smoothly counts a number up to `target` once `active`. Under reduced motion
 * it returns the target immediately.
 */
export function useCountUp(target: number, active: boolean, duration = 1100, reduced = false) {
  const [val, setVal] = useState(reduced ? target : 0);
  useEffect(() => {
    if (!active) return;
    if (reduced) {
      setVal(target);
      return;
    }
    let raf = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - t, 3);
      setVal(Math.round(target * eased));
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, active, duration, reduced]);
  return val;
}

/**
 * A "live" integer that idles around a base value with small jitter, evoking a
 * ticking player count / TPS readout. Static (base) under reduced motion.
 */
export function useJitter(base: number, swing: number, active: boolean, ms = 2600, reduced = false) {
  const [val, setVal] = useState(base);
  useEffect(() => {
    if (!active || reduced) {
      setVal(base);
      return;
    }
    const id = window.setInterval(() => {
      if (document.hidden) return;
      const delta = Math.round((Math.random() - 0.45) * swing);
      setVal((v) => Math.max(base - swing, Math.min(base + swing, v + delta)));
    }, ms);
    return () => window.clearInterval(id);
  }, [base, swing, active, ms, reduced]);
  return val;
}

/** Types out lines char-by-char once active. Returns fully-typed under reduced motion. */
export function useTypedLines(lines: string[], active: boolean, reduced = false) {
  const [done, setDone] = useState<string[]>(reduced || !active ? (active ? lines : []) : []);
  const [current, setCurrent] = useState("");
  const [caret, setCaret] = useState(reduced ? lines.length : 0);
  useEffect(() => {
    if (!active) return;
    if (reduced) {
      setDone(lines);
      setCaret(lines.length);
      return;
    }
    setDone([]);
    setCurrent("");
    setCaret(0);
    let li = 0;
    let ci = 0;
    let timer: ReturnType<typeof setTimeout>;
    const step = () => {
      if (li >= lines.length) return;
      const line = lines[li];
      if (ci <= line.length) {
        setCurrent(line.slice(0, ci));
        ci += 1;
        timer = setTimeout(step, 18 + Math.random() * 26);
      } else {
        setDone((d) => [...d, line]);
        setCaret(li + 1);
        li += 1;
        ci = 0;
        setCurrent("");
        timer = setTimeout(step, 340);
      }
    };
    timer = setTimeout(step, 500);
    return () => clearTimeout(timer);
  }, [active, reduced, lines]);
  return { done, current, caret };
}

/**
 * Scroll-linked progress (0→1) for how far a section's top has travelled through
 * the viewport. Used for the editorial reason "spine". 0 under reduced motion is
 * fine — but we still want the spine full when the section is read, so it tracks
 * regardless and is just not animated by CSS.
 */
export function useScrollProgress<T extends HTMLElement = HTMLDivElement>() {
  const ref = useRef<T | null>(null);
  const [p, setP] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    const compute = () => {
      raf = 0;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      // 0 when the top hits 70% of viewport, 1 when the bottom passes 40%.
      const total = r.height + vh * 0.3;
      const travelled = vh * 0.7 - r.top;
      setP(Math.max(0, Math.min(1, travelled / total)));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(compute);
    };
    compute();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);
  return { ref, p };
}

/** Small parallax offset (px) driven by scroll, capped. Zero under reduced motion. */
export function useParallax<T extends HTMLElement = HTMLDivElement>(strength = 0.12, max = 60, reduced = false) {
  const ref = useRef<T | null>(null);
  const [y, setY] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    let raf = 0;
    const compute = () => {
      raf = 0;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      const center = r.top + r.height / 2 - vh / 2;
      setY(Math.max(-max, Math.min(max, -center * strength)));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(compute);
    };
    compute();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [strength, max, reduced]);
  return { ref, y };
}

/* ── atoms ─────────────────────────────────────────────────────────────── */

const ICONS: Record<IconKey, (p: { size?: number; className?: string }) => React.ReactElement> = {
  bolt: IconBolt,
  apps: IconApps,
  terminal: IconTerminal,
  shield: IconShield,
  gauge: IconGauge,
  users: IconUsers,
  backup: IconBackup,
  globe: IconGlobe,
  scale: IconScale,
};

export function ReasonIcon({ icon, size = 20, className }: { icon: IconKey; size?: number; className?: string }) {
  const C = ICONS[icon];
  return <C size={size} className={className} />;
}

/** Compact gold 5-star row (matches the existing ReviewCarousel star treatment). */
export function StarRow({ rating = 5, size = "text-sm" }: { rating?: number; size?: string }) {
  const filled = Math.max(0, Math.min(5, rating));
  return (
    <span className={`tracking-[0.12em] ${size}`} aria-label={`${filled} out of 5 stars`}>
      <span className="text-amber-300">{"★".repeat(filled)}</span>
      <span className="text-white/15">{"★".repeat(5 - filled)}</span>
    </span>
  );
}

