/* ── Game-landing PREVIEW directions (scoped, additive) ──────────────────────
   Ambient motion helpers used only by components/marketing/gamelanding/* and
   their /preview/game-* routes. Prefixed `pv-` so they can never collide with
   the shipped design system, and every one is disabled under reduced-motion. */
@keyframes pv-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes pv-float-slow {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}
@keyframes pv-scan {
  0% { transform: translateY(-8%); opacity: 0; }
  12%, 88% { opacity: 1; }
  100% { transform: translateY(108%); opacity: 0; }
}
@keyframes pv-kenburns {
  0% { transform: scale(1.04) translate3d(0, 0, 0); }
  100% { transform: scale(1.14) translate3d(-2%, -2%, 0); }
}
@keyframes pv-sheen {
  0% { transform: translateX(-130%) skewX(-14deg); opacity: 0; }
  35%, 55% { opacity: 0.6; }
  100% { transform: translateX(240%) skewX(-14deg); opacity: 0; }
}
@keyframes pv-grid-pan {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}
@keyframes pv-ring {
  0% { stroke-dashoffset: var(--pv-ring-len, 300); }
  100% { stroke-dashoffset: var(--pv-ring-off, 60); }
}
@keyframes pv-glow-breathe {
  0%, 100% { opacity: 0.55; }
  50% { opacity: 0.9; }
}

.pv-float { animation: pv-float 6s ease-in-out infinite; }
.pv-float-slow { animation: pv-float-slow 8s ease-in-out infinite; }
.pv-scan { animation: pv-scan 5.2s ease-in-out infinite; }
.pv-kenburns { animation: pv-kenburns 22s ease-in-out infinite alternate; }
.pv-sheen { animation: pv-sheen 6s ease-in-out infinite; }
.pv-grid-pan { animation: pv-grid-pan 3.4s linear infinite; }
.pv-ring-draw { animation: pv-ring 1.4s cubic-bezier(0.22, 1, 0.36, 1) forwards; }
.pv-glow-breathe { animation: pv-glow-breathe 4.5s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .pv-float,
  .pv-float-slow,
  .pv-scan,
  .pv-kenburns,
  .pv-sheen,
  .pv-grid-pan,
  .pv-ring-draw,
  .pv-glow-breathe {
    animation: none;
  }
}

