"use client";

/**
 * DIRECTION A — "Cinematic Live-Ops".
 *
 * A full-bleed cinematic game-art hero with a navy-scrimmed, asymmetric split:
 * headline + the "47 seconds away" speed hook on the left, and a floating,
 * genuinely-animated LIVE server control panel overlapping the art on the right
 * (ticking player count, a drawn TPS graph, a streaming console). Motion
 * signature = live telemetry + a slow scroll parallax on the art. Below the fold
 * a bento of buying-reasons, premium plans, and compact 5-star reviews.
 *
 * Net-new, preview-only. Touches no live page or shared component.
 */

import Link from "next/link";
import { useState } from "react";
import type { PreviewGame } from "./data";
import {
  usePrefersReducedMotion,
  useInViewOnce,
  useJitter,
  useCountUp,
  useParallax,
  StarRow,
  ReasonIcon,
} from "./kit";
import { GameLogo } from "@/components/marketing/GameLogo";
import { IconBolt, IconShield, IconNvme, IconGlobe, IconCheck } from "@/components/marketing/icons";

/* ── Live TPS sparkline (draws on view, live playhead) ───────────────────── */
function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
  const w = 220;
  const h = 46;
  const min = 19.5;
  const max = 20.2;
  const step = w / (pts.length - 1);
  const coords = pts.map((v, i) => {
    const x = i * step;
    const y = h - ((v - min) / (max - min)) * h;
    return [x, y] as const;
  });
  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
  const area = `${line} L${w} ${h} L0 ${h} Z`;
  const [ex, ey] = coords[coords.length - 1];
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
      <defs>
        <linearGradient id="pv-tps-fill" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
          <stop offset="100%" stopColor={accent} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={area} fill="url(#pv-tps-fill)" />
      <path
        d={line}
        fill="none"
        stroke={accent}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={
          reduced || !active
            ? undefined
            : { strokeDasharray: 700, strokeDashoffset: 700, animation: "pv-ring 1.6s ease-out forwards" }
        }
        // reuse pv-ring keyframe (dashoffset → 0) via CSS var defaults
      />
      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
    </svg>
  );
}

/* ── Floating live control panel ─────────────────────────────────────────── */
function LiveOpsPanel({ game }: { game: PreviewGame }) {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const totalSlots = 60;
  const players = useJitter(47, 3, seen, 2400, reduced);
  const filled = Math.min(totalSlots, players);
  const cpu = useCountUp(38, seen, 1200, reduced);
  const ping = useJitter(12, 2, seen, 3000, reduced);

  const console = [
    { t: "Steve joined the game", c: "text-emerald-300" },
    { t: "Notch joined the game", c: "text-emerald-300" },
    { t: "[Oxide] Loaded 14 plugins", c: "text-slate-400" },
    { t: "Auto-save complete (0.4s)", c: "text-slate-500" },
  ];

  return (
    <div ref={ref} className={reduced ? "" : "pv-float"}>
      <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-[#080d18]/85 shadow-2xl shadow-black/50 backdrop-blur-xl">
        {/* accent aura */}
        <div
          className="pointer-events-none absolute -inset-16 -z-10 opacity-70"
          style={{ background: `radial-gradient(45% 45% at 80% 0%, ${game.accent}33, transparent 70%)` }}
          aria-hidden
        />
        {/* header */}
        <div className="flex items-center gap-2 border-b border-white/[0.06] bg-white/[0.02] px-4 py-2.5">
          <GameLogo family={game.family} size={22} />
          <span className="ml-0.5 truncate text-[11px] font-medium text-slate-300">{game.worldName}</span>
          <span className="ml-auto inline-flex shrink-0 items-center gap-1.5 rounded-full bg-emerald-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            running
          </span>
        </div>

        <div className="space-y-4 p-4">
          {/* live stat row */}
          <div className="grid grid-cols-3 gap-2.5">
            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <p className="text-[10px] uppercase tracking-wide text-slate-500">Players</p>
              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
                {filled}
                <span className="text-sm text-slate-500">/{totalSlots}</span>
              </p>
            </div>
            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <p className="text-[10px] uppercase tracking-wide text-slate-500">Ping</p>
              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
                {ping}
                <span className="text-sm text-slate-500"> ms</span>
              </p>
            </div>
            <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <p className="text-[10px] uppercase tracking-wide text-slate-500">CPU</p>
              <p className="mt-0.5 font-mono text-lg font-semibold text-white tabular-nums">
                {cpu}
                <span className="text-sm text-slate-500">%</span>
              </p>
            </div>
          </div>

          {/* TPS graph */}
          <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] px-3.5 pb-2 pt-3">
