/**
 * DIRECTION B — "Editorial Magazine".
 *
 * A print-inspired, deliberately asymmetric layout: a framed key-art block with
 * a slow ken-burns drift on one side, an editorial text column on the other, an
 * overline masthead, and — the signature — a vertical rail of numbered
 * buying-reasons with a scroll-linked progress "spine" running beside a STICKY,
 * animated plan card (a 47-second deploy ring that counts up as it pins).
 * Motion signature = staggered editorial reveals + ken-burns + scroll spine +
 * sticky pinning. Lots of whitespace, big type, minimal chrome.
 *
 * Net-new, preview-only. Touches no live page or shared component.
 */

import Link from "next/link";
import { useState } from "react";
import type { PreviewGame } from "./data";
import { usePrefersReducedMotion, useInViewOnce, useScrollProgress, useCountUp, StarRow } from "./kit";
