import { IconCheck, IconBolt } from "@/components/marketing/icons";

/* ── 47-second deploy ring (counts up + fills on view) ───────────────────── */
function DeployRing({ accent }: { accent: string }) {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const val = useCountUp(47, seen, 1300, reduced);
  const r = 34;
  const c = 2 * Math.PI * r;
  const offset = c * (1 - Math.min(1, val / 47));
  return (
    <div ref={ref} className="flex items-center gap-4">
      <div className="relative h-[92px] w-[92px] shrink-0">
        <svg viewBox="0 0 92 92" className="h-full w-full -rotate-90">
          <circle cx="46" cy="46" r={r} fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="6" />
          <circle
            cx="46"
            cy="46"
            r={r}
            fill="none"
            stroke={accent}
            strokeWidth="6"
            strokeLinecap="round"
            strokeDasharray={c}
            strokeDashoffset={offset}
          />
        </svg>
        <div className="absolute inset-0 flex flex-col items-center justify-center">
          <span className="font-mono text-2xl font-bold tabular-nums text-white">{val}</span>
          <span className="text-[10px] font-medium uppercase tracking-wide text-slate-500">sec</span>
        </div>
      </div>
      <div>
        <p className="text-sm font-semibold text-white">Live in 47 seconds</p>
        <p className="mt-1 text-xs leading-relaxed text-slate-400">
          From checkout to a running, connect-ready server — measured, not marketing.
        </p>
      </div>
    </div>
  );
}

