function ReasonRow({ game, r, delay }: { game: PreviewGame; r: PreviewGame["reasons"][number]; delay: number }) {
  const { ref, seen } = useInViewOnce<HTMLLIElement>();
  return (
    <li
      ref={ref}
      className={`relative transition-all duration-700 ease-out ${seen ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"}`}
      style={{ transitionDelay: `${delay}ms` }}
    >
      {/* node dot on the spine */}
      <span
        className="absolute -left-[26px] top-1.5 h-3 w-3 rounded-full ring-4 ring-navy-950"
        style={{ background: game.accent }}
        aria-hidden
      />
      <div className="flex items-baseline gap-4">
        <span className="font-mono text-3xl font-bold tabular-nums" style={{ color: `${game.accent}` }}>
          {r.n}
        </span>
        <div>
          <h3 className="text-xl font-semibold text-white">{r.title}</h3>
          <p className="mt-2 max-w-lg text-[15px] leading-relaxed text-slate-400">{r.body}</p>
        </div>
      </div>
    </li>
  );
}

"use client";

/**
 * DIRECTION C — "Command Deck".
 *
 * The hero is a single premium glass CONSOLE: the game art sits inside a HUD
 * viewport (corner brackets, a sweeping scan line, a LIVE tag) beside a rail of
 * animated stat gauges that fill and jitter like real telemetry, over a
 * deploy TERMINAL that types out a boot sequence ending "✓ online in 47s".
 * Motion signature = HUD scan + typing terminal + gauges filling/pulsing + a
 * slow drifting grid. Sci-fi mission-control, distinct from the cinematic and
 * editorial directions. Below: a loadout spec rail, plan "loadouts", reviews.
 *
 * Net-new, preview-only. Touches no live page or shared component.
 */

import Link from "next/link";
import { useState } from "react";
import type { PreviewGame } from "./data";
import { usePrefersReducedMotion, useInViewOnce, useJitter, StarRow, ReasonIcon } from "./kit";
import { useTypedLines } from "./kit";
import { GameLogo } from "@/components/marketing/GameLogo";
import { IconGlobe, IconUsers, IconNvme, IconClock, IconCheck, IconBolt } from "@/components/marketing/icons";

/* ── animated telemetry gauge ────────────────────────────────────────────── */
function Gauge({
  label,
  value,
  suffix,
  pct,
  accent,
  active,
  reduced,
  delay,
}: {
  label: string;
  value: number | string;
  suffix?: string;
  pct: number;
  accent: string;
  active: boolean;
  reduced: boolean;
  delay: number;
}) {
  return (
    <div>
      <div className="mb-1.5 flex items-baseline justify-between">
        <span className="text-[11px] font-medium uppercase tracking-wide text-slate-400">{label}</span>
        <span className="font-mono text-sm font-semibold tabular-nums text-white">
          {value}
          {suffix && <span className="text-slate-500">{suffix}</span>}
        </span>
      </div>
      <div className="h-2 w-full overflow-hidden rounded-full bg-white/[0.06]">
        <div
          className={`h-full origin-left rounded-full ${reduced || !active ? "" : "motion-safe:animate-grow-x"}`}
          style={{
            width: `${pct}%`,
            background: `linear-gradient(90deg, #3b82f6, ${accent})`,
            animationDelay: `${delay}ms`,
          }}
        />
      </div>
    </div>
  );
}

/* ── the console centerpiece ─────────────────────────────────────────────── */
function CommandDeck({ game }: { game: PreviewGame }) {
  const reduced = usePrefersReducedMotion();
  const { ref, seen } = useInViewOnce<HTMLDivElement>();
  const [imgOk, setImgOk] = useState(true);
  const players = useJitter(28, 3, seen, 2500, reduced);
  const cpu = useJitter(41, 4, seen, 2200, reduced);
  const ram = useJitter(63, 3, seen, 2800, reduced);
  const { done, current, caret } = useTypedLines(game.boot, seen, reduced);

  return (
    <div ref={ref} className={reduced ? "" : "pv-float-slow"}>
      <div
        className="relative overflow-hidden rounded-3xl border border-white/10 bg-[#070c17]/90 backdrop-blur-xl"
        style={{ boxShadow: `0 40px 120px -50px ${game.accent}80, 0 0 0 1px rgba(255,255,255,0.04)` }}
      >
        {/* drifting grid backdrop */}
        <div
          className={`pointer-events-none absolute inset-0 opacity-[0.5] ${reduced ? "" : "pv-grid-pan"}`}
          style={{
            backgroundImage:
              "linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px)",
            backgroundSize: "40px 40px",
          }}
          aria-hidden
        />
        <div
          className="pointer-events-none absolute -inset-24 -z-0 opacity-70"
          style={{ background: `radial-gradient(40% 40% at 85% 0%, ${game.accent}30, transparent 70%)` }}
          aria-hidden
        />

        {/* deck header */}
        <div className="relative flex items-center gap-3 border-b border-white/[0.07] bg-white/[0.02] px-5 py-3">
          <GameLogo family={game.family} size={26} />
          <span className="text-sm font-semibold text-white">{game.worldName}</span>
          <span className="hidden font-mono text-[11px] text-slate-500 sm:inline">{game.region}</span>
          <span className="ml-auto inline-flex items-center gap-1.5 rounded-full bg-emerald-500/12 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-300">
            <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" />
            live
          </span>
        </div>

        <div className="relative grid gap-4 p-4 lg:grid-cols-5 lg:p-5">
          {/* HUD viewport */}
          <div className="lg:col-span-3">
            <div className="relative aspect-[16/10] overflow-hidden rounded-2xl border border-white/10 bg-black">
              {imgOk && (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={`/games/art/${game.artSlug}_hero.jpg`}
                  alt={`${game.name} live viewport`}
                  onError={() => setImgOk(false)}
                  className="h-full w-full object-cover object-center"
                />
              )}
              {/* tint + vignette */}
              <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-navy-950/60 via-transparent to-navy-950/20" aria-hidden />
              {/* scan line */}
              {!reduced && (
                <div
                  className="pv-scan pointer-events-none absolute inset-x-0 top-0 h-16"
                  style={{ background: `linear-gradient(to bottom, ${game.accent}00, ${game.accent}22, ${game.accent}00)` }}
                  aria-hidden
                />
              )}
              {/* corner brackets */}
              {["left-3 top-3 border-l-2 border-t-2", "right-3 top-3 border-r-2 border-t-2", "left-3 bottom-3 border-l-2 border-b-2", "right-3 bottom-3 border-r-2 border-b-2"].map(
                (pos) => (
                  <span
                    key={pos}
                    className={`absolute h-6 w-6 rounded-[3px] ${pos}`}
                    style={{ borderColor: `${game.accent}cc` }}
                    aria-hidden
                  />
                ),
              )}
              {/* live tag + telemetry strip */}
              <div className="absolute left-4 top-4 inline-flex items-center gap-1.5 rounded-md bg-navy-950/70 px-2 py-1 font-mono text-[10px] uppercase tracking-wider text-slate-200 backdrop-blur-sm">
                <span className="h-1.5 w-1.5 rounded-full bg-red-500 motion-safe:animate-pulse-dot" /> rec · {game.name}
              </div>
              <div className="absolute inset-x-3 bottom-3 flex items-center justify-between font-mono text-[10px] text-slate-300">
                <span className="rounded bg-navy-950/70 px-2 py-1 backdrop-blur-sm">{game.region}</span>
                <span className="rounded bg-navy-950/70 px-2 py-1 backdrop-blur-sm tabular-nums">
                  {players} online · 60 fps
                </span>
              </div>
            </div>
          </div>

          {/* gauges rail */}
          <div className="flex flex-col gap-4 lg:col-span-2">
            <div className="rounded-2xl border border-white/[0.07] bg-white/[0.02] p-4">
              <p className="mb-4 text-[11px] font-semibold uppercase tracking-wider text-slate-500">Live telemetry</p>
              <div className="space-y-4">
                <Gauge label="Players" value={players} suffix="/32" pct={(players / 32) * 100} accent={game.accent} active={seen} reduced={reduced} delay={80} />
                <Gauge label="CPU" value={cpu} suffix="%" pct={cpu} accent={game.accent} active={seen} reduced={reduced} delay={160} />
                <Gauge label="Memory" value={ram} suffix="%" pct={ram} accent={game.accent} active={seen} reduced={reduced} delay={240} />
                <Gauge label="TPS" value="20.0" pct={100} accent={game.accent} active={seen} reduced={reduced} delay={320} />
              </div>
            </div>
            <div className="flex items-center justify-between rounded-2xl border border-white/[0.07] bg-white/[0.02] px-4 py-3 text-[11px] text-slate-400">
              <span className="font-mono">uptime 4d 06h</span>
              <span className="inline-flex items-center gap-1.5 text-emerald-300">
                <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse-dot" /> healthy
              </span>
            </div>
          </div>

          {/* deploy terminal */}
          <div className="lg:col-span-5">
            <div className="rounded-2xl border border-white/[0.07] bg-black/50 p-4 font-mono text-[12px] leading-relaxed">
              {done.map((l, i) => {
                const ok = l.startsWith("✓");
                return (
                  <div key={i} className={ok ? "font-semibold" : "text-slate-400"} style={ok ? { color: game.accent } : undefined}>
                    {l}
                  </div>
                );
              })}
              {caret < game.boot.length && (
                <div className="text-slate-300">
                  {current}
                  <span className="ml-0.5 inline-block h-3.5 w-1.5 translate-y-[2px] bg-slate-300 motion-safe:animate-blink" />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

