import { chromium } from 'playwright';

const OUT = '/opt/nxeon-staging/.design-previews';
const BASE = 'http://localhost:3777';
const routes = [
  ['preview', 'index'],
  ['preview/game-cinematic', 'A-cinematic-rust'],
  ['preview/game-editorial', 'B-editorial-satisfactory'],
  ['preview/game-console', 'C-console-palworld'],
];
const viewports = [
  ['desktop', 1440, 900],
  ['mobile', 390, 844],
];

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function autoScroll(page) {
  await page.evaluate(async () => {
    await new Promise((resolve) => {
      let y = 0;
      const step = () => {
        window.scrollBy(0, Math.round(window.innerHeight * 0.7));
        y += window.innerHeight * 0.7;
        if (y >= document.body.scrollHeight + window.innerHeight) {
          resolve();
        } else {
          setTimeout(step, 180);
        }
      };
      step();
    });
  });
  await sleep(400);
  await page.evaluate(() => window.scrollTo(0, 0));
  await sleep(700);
}

const browser = await chromium.launch();
for (const [label, w, h] of viewports) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: label === 'mobile' ? 2 : 1 });
  const page = await ctx.newPage();
  const errs = [];
  page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
  page.on('pageerror', (e) => errs.push('PAGEERROR: ' + e.message));
  for (const [route, name] of routes) {
    await page.goto(`${BASE}/${route}`, { waitUntil: 'networkidle', timeout: 60000 });
    await sleep(600);
    await autoScroll(page);
    await sleep(400);
    const file = `${OUT}/${name}.${label}.png`;
    await page.screenshot({ path: file, fullPage: true });
    console.log(`saved ${file}${errs.length ? '  ⚠ ' + errs.length + ' console errs' : ''}`);
    if (errs.length) { console.log('   ' + errs.slice(0, 4).join('\n   ')); errs.length = 0; }
  }
  await ctx.close();
}
await browser.close();
console.log('done');

